import Vue from "vue";
import Router from "vue-router";
import {
  Sales,
  Config,
  Barrels,
  Workers,
  Dashboard,
  Inventario,
  KegDetails,
  VIPClients,
  LineDetails,
  ExpandedList,
  WorkerDetails,
  ClientDetails,
} from "../views";

Vue.use(Router);

export default new Router({
  mode: "history",
  base: "/client/",
  routes: [
    // El login anterior era decorativo (sin auth real ni guards); mientras
    // no haya autenticación de verdad, entrar directo es más honesto
    {
      path: "/",
      redirect: "/dashboard"
    },
    {
      path: "/dashboard",
      name: "dashboard",
      component: Dashboard
    },
    {
      path: "/barrels",
      name: "barrels",
      component: Barrels
    },
    {
      path: "/line-details/:id",
      name: "line-details",
      component: LineDetails
    },
    {
      path: "/keg-details/:id",
      name: "keg-details",
      component: KegDetails
    },
    {
      path: "/workers",
      name: "workers",
      component: Workers
    },
    {
      path: "/worker-details/:worker",
      name: "worker-details",
      component: WorkerDetails
    },
    {
      path: "/sales",
      name: "sales",
      component: Sales
    },
    {
      path: "/list-details",
      name: "list-details",
      component: ExpandedList
    },
    {
      path: "/inventario",
      name: "inventario",
      component: Inventario
    },
    {
      path: "/configuration",
      name: "config",
      component: Config
    },
    {
      path: "/Clients",
      name: "VIPClients",
      component: VIPClients
    },
    {
      path: "/client-details/:id",
      name: "client-details",
      component: ClientDetails
    },
    {
      path: "*",
      redirect: "/dashboard"
    }
  ]
});