import Api, { SetIp } from "../../service/api";
import config from "../../config";

const state = {
  BASE_URL: "",
  loggedIn: false,
  connectionStatus: false,
  bootstrapped: false,
  // Plugins instalados en el server (el manager oculta secciones sin plugin)
  capabilities: { rewards: false },
  snackbar: { visible: false, message: "", color: "info" },
  workers: [],
  placeInfo: {
    name: "Chikilla",
    branch: "Taka & Chikilla",
    instagram: "@chikillacraftbeer",
    facebook: "/chikilla.ensenada",
    twitter: ""
  },
  prices: {
    pint: 90,
    taster: 35,
    flight: 15
  },
};


const mutations = {
  SET_USER(state, user) {
    return (state.loggedIn = user);
  },
  SET_WORKERS(state, response) {
    // console.warn(response);
    return (state.workers = response);
  },
  UPDATE_WORKER(state, workerUpdated) {
    const index = state.workers.findIndex(
      worker => worker._id === workerUpdated._id
    );
    if (index !== -1) state.workers.splice(index, 1, workerUpdated);
  },
  NEW_WORKER(state, newWorker) {
    return state.workers.push(newWorker);
  },
  REMOVE_WORKER(state, workerId) {
    const index = state.workers.findIndex(item => item._id === workerId);
    index === -1 ? null : state.workers.splice(index, 1);
  },
  SET_PLACE_INFO(state, placeInfo) {
    state.placeInfo = placeInfo;
  },
  CONNECTED(state) {
    state.connectionStatus = true;
  },
  DISCONNECTED(state) {
    state.connectionStatus = false;
  },
  SET_URL(state, url) {
    SetIp(url);
    state.BASE_URL = `${window.location.protocol}//${url}`;
  },
  BOOTSTRAPPED(state) {
    state.bootstrapped = true;
  },
  SET_CAPABILITIES(state, capabilities) {
    state.capabilities = { ...state.capabilities, ...capabilities };
  },
  SHOW_SNACKBAR(state, { message, color }) {
    state.snackbar = { visible: true, message, color: color || "info" };
  },
  HIDE_SNACKBAR(state) {
    state.snackbar = { ...state.snackbar, visible: false };
  }
};

const actions = {
  async logIn({ commit }) {
    commit("SET_USER", true);
  },
  // Carga inicial de todo el estado (antes vivía en Dashboard.beforeMount, lo
  // que dejaba las demás vistas sin datos al entrar directo por URL).
  // force=true re-sincroniza tras una reconexión del socket.
  async bootstrap({ commit, dispatch, state }, force = false) {
    if (state.bootstrapped && !force) return;
    // Una vista puede montar antes de que App resuelva el host; sin esto la
    // petición salía relativa al dev server (p. ej. :8080/getSummary → 404)
    if (!state.BASE_URL) commit("SET_URL", await config.BASE_URL());
    const response = await Api().get("/getSummary");
    if (!response.data.confirmation) throw new Error("getSummary falló");

    const { data } = response.data;
    const { kegs, lines, beers, emergencyCard } = data;
    const { stock, workers, placeInfo, sales } = data;

    dispatch("Lines/setLines", { data: kegs, lines, beers, emergencyCard }, { root: true });
    dispatch("Sales/setSales", sales, { root: true });
    dispatch("Stock/setStock", stock, { root: true });
    commit("SET_WORKERS", workers);
    commit("SET_PLACE_INFO", placeInfo);
    commit("BOOTSTRAPPED");

    // Plugins disponibles (best-effort: si falla, quedan los defaults)
    try {
      const caps = await Api().get("/capabilities");
      if (caps.data.confirmation === "success")
        commit("SET_CAPABILITIES", caps.data.data);
    } catch (e) {
      console.warn("capabilities no disponible:", e.message);
    }
  },
  notify({ commit }, payload) {
    commit(
      "SHOW_SNACKBAR",
      typeof payload === "string" ? { message: payload } : payload
    );
  },
  async getWorkers({ commit }) {
    try {
      let response = await Api().get("/getWorkers");
      commit("SET_WORKERS", response.data.data);
    } catch (e) {
      console.error("getWorkers:", e);
    }
  },
  setWorkers({ commit }, workers) {
    commit("SET_WORKERS", workers);
  },
  updateWorker({ commit }, workerUpdated) {
    commit("UPDATE_WORKER", workerUpdated);
  },
  newWorker({ commit }, newWorker) {
    commit("NEW_WORKER", newWorker);
  },
  removeWorker({ commit }, workerId) {
    commit("REMOVE_WORKER", workerId);
  },
  setPlaceInfo({ commit }, placeInfo) {
    commit("SET_PLACE_INFO", placeInfo);
  },
  connected({ commit }) {
    commit("CONNECTED");
  },
  disconnected({ commit }) {
    commit("DISCONNECTED");
  },
  setURL({ commit }, URL) {
    commit("SET_URL", URL);
  }
};

const getters = {
  getWorker: state => workerId => {
    return state.workers.find(worker => {
      if (workerId === worker._id) return worker;
    });
  },
  getWorkerByCardId: state => cardId => {
    return state.workers.find(worker => cardId === worker.cardId);
  },
  getNames: state => {
    return state.workers.map(worker => worker.nombre);
  }
};

export default {
  namespaced: true,
  state,
  mutations,
  actions,
  getters
};
